import 'package:async_task/async_task.dart';

void main() async {
  var tasks = [PrimeChecker(8779), PrimeChecker(1046527)];
  var executor = AsyncExecutor(sequential:false, parallelism:2, taskTypeRegister:()=>[PrimeChecker(0)]);
  var executions = executor.executeAll(tasks);
  await Future.wait(executions);
  for (var t in tasks) print('${t.n} -> ${t.result}');
}

class PrimeChecker extends AsyncTask<int,bool>{
  final int n; PrimeChecker(this.n);
  @override AsyncTask<int,bool> instantiate(int p)=>PrimeChecker(p);
  @override int parameters()=>n;
  @override FutureOr<bool> run()=>isPrime(n);
  bool isPrime(int n){ if(n<2)return false; var l=n~/2; for(var p=2;p<=l;++p)if(n%p==0)return false; return true; }
}
